await sequelize.transaction(async (t) => {
  const [lock, created] = await LockRecord.findOrCreate({
    where: { lockable: key },
    defaults: { owner: sessionId, acquiredAt: new Date() },
    lock: t.LOCK.UPDATE,
    transaction: t,
  });
  if (!created && lock.owner !== sessionId) {
    throw new Error(`locked by ${lock.owner}`);
  }
});
